import express from 'express';
import { v4: uuidv4 } from 'uuid';

const app = express();
app.use(express.json());
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  next();
});

const todosStore = [];

const validateTodoTitle = (title) => {
  if (!title || typeof title !== 'string' || title.length < 1 || title.length > 100) {
    throw new Error('Invalid todo title');
  }
};

const getTodos = (filterCompleted) => {
  return filterCompleted ? todosStore.filter((todo) => todo.completed) : todosStore;
};

app.get('/todos', (req, res) => {
  const completedFilter = req.query.completed === 'true';
  try {
    const todos = getTodos(completedFilter);
    res.json(todos.map((todo) => ({ ...todo, id: todo.id.toString() })));
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.get('/todos/:id', (req, res) => {
  const id = req.params.id;
  try {
    const todo = todosStore.find((todo) => todo.id === id);
    if (!todo) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    res.json(todo);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.post('/todos', (req, res) => {
  const { title } = req.body;
  try {
    validateTodoTitle(title);
    const newTodo = {
      id: uuidv4(),
      title,
      completed: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    todosStore.push(newTodo);
    res.json(newTodo);
  } catch (error) {
    if (error.message.includes('Invalid todo title')) {
      return res.status(400).json({ error: 'Invalid todo title' });
    }
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.put('/todos/:id', (req, res) => {
  const id = req.params.id;
  try {
    const existingTodo = todosStore.find((todo) => todo.id === id);
    if (!existingTodo) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    const { title, completed } = req.body;
    validateTodoTitle(title);
    existingTodo.title = title;
    existingTodo.completed = completed ?? false;
    existingTodo.updatedAt = new Date().toISOString();
    res.json(existingTodo);
  } catch (error) {
    if (error.message.includes('Invalid todo title')) {
      return res.status(400).json({ error: 'Invalid todo title' });
    }
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.delete('/todos/:id', (req, res) => {
  const id = req.params.id;
  try {
    const index = todosStore.findIndex((todo) => todo.id === id);
    if (index === -1) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    todosStore.splice(index, 1);
    res.json({ message: 'Todo deleted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

export default app;
