import request from 'supertest';
import app from './todo-server';

describe('Todo API', () => {
  it('GET /todos returns all todos', async () => {
    const response = await request(app).get('/todos');
    expect(response.status).toBe(200);
    expect(response.body.length).toBe(0);
  });

  it('GET /todos with completed=true filter returns only completed todos', async () => {
    const todo = { id: '123', title: 'Test Todo', completed: true, createdAt: '', updatedAt: '' };
    await request(app).post('/todos').send(todo).expect(201);
    const response = await request(app).get('/todos?completed=true');
    expect(response.status).toBe(200);
    expect(response.body.length).toBe(1);
  });

  it('GET /todos/:id returns single todo', async () => {
    const todo = { id: '123', title: 'Test Todo', completed: false, createdAt: '', updatedAt: '' };
    await request(app).post('/todos').send(todo).expect(201);
    const response = await request(app).get('/todos/123');
    expect(response.status).toBe(200);
    expect(response.body.title).toBe('Test Todo');
  });

  it('POST /todos creates new todo', async () => {
    const todo = { title: 'New Todo' };
    const response = await request(app).post('/todos').send(todo).expect(201);
    expect(response.body.title).toBe('New Todo');
  });

  it('PUT /todos/:id updates existing todo', async () => {
    const existingTodo = { id: '123', title: 'Old Todo', completed: false, createdAt: '', updatedAt: '' };
    await request(app).post('/todos').send(existingTodo).expect(201);
    const updatedTodo = { id: '123', title: 'New Title' };
    const response = await request(app).put('/todos/123').send(updatedTodo).expect(200);
    expect(response.body.title).toBe('New Title');
  });

  it('DELETE /todos/:id deletes todo', async () => {
    const todo = { id: '123', title: 'Test Todo', completed: false, createdAt: '', updatedAt: '' };
    await request(app).post('/todos').send(todo).expect(201);
    const response = await request(app).delete('/todos/123').expect(200);
    expect(response.body.message).toBe('Todo deleted successfully');
  });

  it('POST /todos with invalid title returns 400 error', async () => {
    const todo = { title: '' };
    const response = await request(app).post('/todos').send(todo).expect(400);
    expect(response.body.error).toBe('Invalid todo title');
  });
});
